public UncalcedRecord(RecordInputStream in1){
    // Call the parent constructor to handle common record initialization
    super(in1);

    // Read the length of the uncalculated data block
    this.dataLength = in1.readInt();

    // Allocate a buffer for the raw data and read it from the stream
    this.rawData = new byte[this.dataLength];
    in1.readFully(this.rawData);

    // Optionally, store the offset position for later use
    this.offset = in1.getPosition() - this.dataLength;
}

