    if (nArgs < 1){return ErrorEval.VALUE_INVALID;}
    if (nArgs > 30){return ErrorEval.VALUE_INVALID;}
    int temp = 0;
    for (int i = 0; i < nArgs; i++){
        if (args[i] is NumberEval)
        {
            temp += (int)((NumberEval)args[i]).Value;
        }
        else
