public override IDictionary<string, SubmoduleStatus> Call()
{
    CheckCallable();
    try
    {
        SubmoduleWalk generator = SubmoduleWalk.ForIndex(repo);
        if (!paths.IsEmpty())
        {
            generator.SetFilter(PathFilterGroup.CreateFromStrings(paths));
        }
        IDictionary<string, SubmoduleStatus> statuses = new Dictionary<string, SubmoduleStatus>();
        while (generator.Next())
        {
            SubmoduleStatus status = GetStatus(generator);
            statuses[generator.Path] = status;
        }
        return statuses;
    }
    catch (IOException e)
    {
        throw new JGitInternalException(e.Message, e);
    }
    catch (ConfigInvalidException e)
    {
        throw new JGitInternalException(e.Message, e);
    }
}

public virtual void FromString(string str)
{
    if (str.Length != Constants.OBJECT_ID_STRING_LENGTH)
    {
        throw new ArgumentException(MessageFormat.Format(JGitText.Get().invalidId, str));
    }

    // Convert the hexadecimal string into the internal byte array.
    for (int i = 0; i < Constants.OBJECT_ID_STRING_LENGTH; i += 2)
    {
        // Each pair of characters represents one byte.
        this.bytes[i / 2] = Convert.ToByte(str.Substring(i, 2), 16);
    }
}

