public void consume() {
    boolean skipEofCheck;
    if (p >= 0) {
        if (fetchedEOF) {
            skipEofCheck = p < tokens.size() - 1;
        } else {
            skipEofCheck = false;
        }
    } else {
        skipEofCheck = false;
    }
    if (!skipEofCheck && LA(1) == EOF) {
        throw new IllegalStateException("cannot consume EOF");
    }
    if (sync(p + 1)) {
        p = adjustSeekIndex(p + 1);
    }
}

public void add(int location, E object) {
    if (location < 0 || location > size) {
        throw new IndexOutOfBoundsException("Index: " + location + ", Size: " + size);
    }
    if (size == elements.length) {
        int newCapacity = elements.length * 2 + 1;
        elements = java.util.Arrays.copyOf(elements, newCapacity);
    }
    System.arraycopy(elements, location, elements, location + 1, size - location);
    elements[location] = object;
    size++;
}

