    {
        throw new ParseException("missing body : " + v, idx + 1);
    }
    var shape = ParseShape(body, ctx);
    var args = NewSpatialArgs(op, shape);
    if (v.Length > (edx + 1))
    {
        body = v.Substring(edx + 1).Trim();
        if (body.Length > 0)
